    Eigen::Matrix2d S;                 // tamano fijo, sin reservar memoria
    S << 2, -1,
        -1,  3;

    Eigen::Vector2d b;
    b << 1, 2;

    const Eigen::Vector2d x = S.ldlt().solve(b);
    std::cout << "x = " << x.transpose() << '\n';
    return 0;
}

#include <Eigen/Dense>
#include <iostream>

int main() {
    Eigen::MatrixXd X(4, 2);   // columna 0: unos; columna 1: x
    X << 1, 1,
         1, 2,
         1, 3,
         1, 4;

    Eigen::VectorXd y(4);
    y << 2, 4, 6, 8;

    const Eigen::VectorXd w = X.colPivHouseholderQr().solve(y);
    std::cout << "b = " << w(0) << "  w = " << w(1) << '\n';
    std::cout << "residuo = " << (X * w - y).norm() << '\n';
    return 0;
}

