#include <Eigen/Dense>
#include <iostream>

int main() {
    Eigen::Matrix3d A;
    A << 2, 1, 0,
         1, 3, 1,
         0, 1, 4;

    Eigen::Vector3d b;
    b << 3, 5, 5;

    const Eigen::Vector3d x = A.partialPivLu().solve(b);
    std::cout << "x = " << x.transpose() << '\n';          // 1 1 1
    std::cout << "residuo = " << (A * x - b).norm() << '\n';
    return 0;
}

#include <Eigen/Dense>
#include <iostream>

int main() {
    Eigen::MatrixXd X(5, 2);
    X << 1, 1,
         1, 2,
         1, 3,
         1, 4,
         1, 5;

    Eigen::VectorXd y(5);
    y << 3, 5, 7, 9, 11;

    const Eigen::VectorXd coef = X.completeOrthogonalDecomposition().solve(y);
    std::cout << "intercepto = " << coef(0) << '\n';   // 1
    std::cout << "pendiente  = " << coef(1) << '\n';   // 2
    std::cout << "residuo    = " << (X * coef - y).norm() << '\n';
    return 0;
}

